# M[i][c] is the minhash of column c under hash function h_i.
for i in range(n_hashes):
    for c in columns:
        M[i][c] = INFINITY

for r in rows:
    h = [h_i(r) for h_i in hashes]        # compute every h_i(r) once
    for c in columns:
        if document_c_has_1_in_row(c, r):
            for i in range(n_hashes):
                if h[i] < M[i][c]:
                    M[i][c] = h[i]
